from pathlib import Path
import base64
import re
import subprocess
import tempfile

ROOT = Path("/workspaces/StormTracker")
FRONTEND = ROOT / "frontend"
SRC = FRONTEND / "src"
TESTS = FRONTEND / "tests"

SOURCE = FRONTEND / "doppler-georef-v4.html"
TARGET = FRONTEND / "doppler-georef-v5.html"

for required in [
    SOURCE,
    SRC / "bom-doppler-intake-v1.js",
    SRC / "bom-doppler-georef-v1.js",
    SRC / "bom-doppler-spatial-v1.js",
]:
    if not required.exists():
        raise SystemExit(f"ERROR: missing required file: {required}")

shared_js = base64.b64decode(
    ""
).decode("utf-8")

test_js = base64.b64decode(
    ""
).decode("utf-8")

camera_block = base64.b64decode(
    ""
).decode("utf-8")

(SRC / "stormtracker-camera-v1.js").write_text(
    shared_js,
    encoding="utf-8"
)

TESTS.mkdir(
    parents=True,
    exist_ok=True
)

(TESTS / "run-stormtracker-camera-v1-tests.mjs").write_text(
    test_js,
    encoding="utf-8"
)

text = SOURCE.read_text(
    encoding="utf-8"
)

text = text.replace(
    "StormTracker — Doppler Geolocation V4",
    "StormTracker — Doppler Geolocation V5"
)

text = text.replace(
    "StormTracker Doppler geolocation V4",
    "StormTracker Doppler geolocation V5"
)

mode_pattern = re.compile(
    r'<div class="mode">.*?</div>',
    re.S
)

text, count = mode_pattern.subn(
    """<div class="mode">
      Camera mode: SHARED CUSTOM MOUSE V1. Left-drag pans; right-drag
      rotates/tilts; Shift+left-drag or middle-drag tilts; wheel zooms one
      deterministic step per gesture. Native Cesium camera input remains
      disabled. There is no map-lock toggle.
    </div>""",
    text,
    count=1
)

if count != 1:
    raise SystemExit(
        "ERROR: could not replace V4 camera-mode note."
    )

import_anchor = """import {
  decodeGeoreferencedDoppler,
  geolocatedDopplerSamples
} from "./src/bom-doppler-spatial-v1.js?v=georef-v4";"""

if text.count(import_anchor) != 1:
    raise SystemExit(
        "ERROR: Doppler spatial import anchor changed."
    )

text = text.replace(
    import_anchor,
    import_anchor
    + """

import {
  createStormTrackerCameraController
} from "./src/stormtracker-camera-v1.js?v=camera-v1";""",
    1
)

start_marker = """const scene =
  viewer.scene;"""

end_marker = """const points =
  scene.primitives.add("""

start = text.find(start_marker)
end = text.find(end_marker, start)

if start < 0 or end < 0:
    raise SystemExit(
        "ERROR: V4 camera-block markers not found."
    )

text = (
    text[:start]
    + camera_block
    + text[end:]
)

text = text.replace(
    "DOPPLER GEOLOCATION V4 —",
    "DOPPLER GEOLOCATION V5 —"
)

text = text.replace(
    "Camera movement is deterministic-controls-only while stability is validated.",
    "Shared custom mouse camera active; native Cesium input remains disabled."
)

TARGET.write_text(
    text,
    encoding="utf-8"
)

subprocess.run(
    [
        "node",
        "--check",
        "frontend/src/stormtracker-camera-v1.js"
    ],
    cwd=ROOT,
    check=True
)

html = TARGET.read_text(
    encoding="utf-8"
)

modules = re.findall(
    r'<script type="module">(.*?)</script>',
    html,
    flags=re.S
)

if len(modules) != 1:
    raise SystemExit(
        f"ERROR: expected one V5 module; found {len(modules)}."
    )

with tempfile.NamedTemporaryFile(
    mode="w",
    suffix=".mjs",
    encoding="utf-8",
    delete=False
) as tmp:
    tmp.write(modules[0])
    tmp_path = Path(tmp.name)

try:
    subprocess.run(
        [
            "node",
            "--check",
            str(tmp_path)
        ],
        check=True
    )
finally:
    tmp_path.unlink(
        missing_ok=True
    )

subprocess.run(
    [
        "node",
        "frontend/tests/run-stormtracker-camera-v1-tests.mjs"
    ],
    cwd=ROOT,
    check=True
)

subprocess.run(
    [
        "node",
        "frontend/tests/run-node-tests.mjs"
    ],
    cwd=ROOT,
    check=True
)

print()
print("SUCCESS")
print("Expected:")
print("  7 shared camera controller tests passed.")
print("  14 tests passed.")
print()
print("Commit and push:")
print(
    "git add "
    "frontend/src/stormtracker-camera-v1.js "
    "frontend/doppler-georef-v5.html "
    "frontend/tests/run-stormtracker-camera-v1-tests.mjs"
)
print(
    'git commit -m "Add shared StormTracker mouse camera controller"'
)
print("git push")
print()
print("After Pages deploys:")
print(
    "https://blakesmith-intel.github.io/StormTracker/"
    "doppler-georef-v5.html"
)
print()
print("Mouse controls:")
print("  left drag             = pan")
print("  right drag            = rotate + tilt")
print("  Shift + left drag     = tilt")
print("  middle drag           = tilt")
print("  wheel/trackpad scroll = one zoom step per gesture")
print()
print("Validation:")
print("  1. Leave untouched for 30 seconds.")
print("  2. Camera corrections must remain 0.")
print("  3. Load Mt Stapylton 66; leave untouched 30 seconds.")
print("  4. Test all mouse controls.")
print("  5. Movement must stop immediately when input stops.")
print()
print(
    "This shared module is the suite standard. "
    "Do not copy camera code into individual pages."
)
